+                case Some(a) if !new_analyzer.lteq(self_type, a) =>
+                  error(errors, named + " extends " + st + ", whose self parameter is " + a +
+                        ", but " + named + " is not a subtype of " + a + ".", extension)
+                case _ =>
+              }
+            case _ =>
+          }
+        case None =>
+      }
+      case _ =>
+    }
